function draw(ctx,t,p){
  var W=960,H=540;
  var defs={eta:{min:0.1,max:6,step:0.1,value:1.5},x0:{min:-6,max:6,step:0.1,value:5},y0:{min:-6,max:6,step:0.1,value:4},arrows:{min:0,max:1,step:1,value:1},contours:{min:0,max:1,step:1,value:1},func:{min:0,max:1,step:1,value:0}};
  function val(id){var v=Number(p&&p[id]);return isFinite(v)?v:defs[id].value}
  var mode=p&&p.$mode==='explore'?'explore':'presentation';
  var scene=0,local=0,eta=val('eta'),x0=val('x0'),y0=val('y0'),ar=val('arrows')>=0.5,co=val('contours')>=0.5,fn=val('func')>=0.5;
  if(mode==='presentation'){
    var sec=t*39;
    if(sec<8){scene=0;local=sec/8;eta=1.5;x0=5;y0=4}
    else if(sec<17){scene=1;local=(sec-8)/9;eta=1.5;x0=5;y0=4}
    else if(sec<29){scene=2;local=(sec-17)/12;eta=1.5;x0=5;y0=4}
    else{scene=3;local=(sec-29)/10;eta=0.3+5.2*Math.min(1,local*3);x0=5;y0=4}
    ar=true;co=true;fn=false;
  }
  var a=fn?0.18:0.08,b=fn?0.18:0.18;
  function f(x,y){return a*x*x+b*y*y}
  function gx(x){return 2*a*x} function gy(y){return 2*b*y}
  function path(e,n){var q=[],x=x0,y=y0;q.push([x,y,f(x,y)]);for(var k=0;k<n;k++){x=x-e*gx(x);y=y-e*gy(y);q.push([x,y,f(x,y)])}return q}
  var steps=mode==='presentation'?(scene===0?0:scene===1?0:scene===2?Math.floor(local*18):Math.floor(Math.min(1,local)*18)):Math.floor(t*18);
  var main=path(eta,steps), cases=[];
  if(mode==='presentation'&&scene===3){cases=[path(.3,Math.floor(local*18)),path(1.5,Math.floor(local*18)),path(5.5,Math.floor(local*18))]}
  else cases=[main];
  var R=6,Z=f(6,6),all=[];
  for(var ci=0;ci<cases.length;ci++)for(var qi=0;qi<cases[ci].length;qi++){all.push(cases[ci][qi]);R=Math.max(R,Math.abs(cases[ci][qi][0]),Math.abs(cases[ci][qi][1]));Z=Math.max(Z,cases[ci][qi][2])}
  R=Math.max(R,6);Z=Math.max(Z,1);
  function P(x,y,z){return [480+30*(x-y)/R,292+15*(x+y)/R-112*z/Z]}
  function line(x1,y1,x2,y2,c,w){ctx.strokeStyle=c;ctx.lineWidth=w||1.5;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
  function txt(s,x,y,size,color){ctx.fillStyle=color||'#26364a';ctx.font=(size||17)+'px sans-serif';ctx.fillText(s,x,y)}
  function arrow(x1,y1,x2,y2,c){line(x1,y1,x2,y2,c,2.5);var q=Math.atan2(y2-y1,x2-x1),l=8;line(x2,y2,x2-l*Math.cos(q-.5),y2-l*Math.sin(q-.5),c,2);line(x2,y2,x2-l*Math.cos(q+.5),y2-l*Math.sin(q+.5),c,2)}
  ctx.fillStyle='#f7f9fc';ctx.fillRect(0,0,W,H);ctx.save();ctx.beginPath();ctx.rect(35,85,890,335);ctx.clip();
  txt('z=f(x,y) 的透视投影',55,108,18,'#38506b');
  for(var i=-6;i<=6;i+=1){var last=null;for(var j=-6;j<=6;j+=1){var pp=P(i,j,f(i,j));if(last)line(last[0],last[1],pp[0],pp[1],'#b8d5df',1);last=pp}}
  for(var j=-6;j<=6;j+=1){var last2=null;for(var i=-6;i<=6;i+=1){var pp2=P(i,j,f(i,j));if(last2)line(last2[0],last2[1],pp2[0],pp2[1],'#b8d5df',1);last2=pp2}}
  var org=P(0,0,0);line(org[0]-20,org[1],org[0]+20,org[1],'#526579',2);line(org[0],org[1]-18,org[0],org[1]+18,'#526579',2);txt('最优点 (0,0)',org[0]+8,org[1]-8,16,'#176b58');
  if(co){for(var rad=1;rad<=5;rad++){ctx.beginPath();for(var u=0;u<=Math.PI*2+.1;u+=.12){var xx=rad*Math.cos(u)/Math.sqrt(a/.08),yy=rad*Math.sin(u)/Math.sqrt(b/.18),pp=P(xx,yy,0);if(u===0)ctx.moveTo(pp[0],pp[1]);else ctx.lineTo(pp[0],pp[1])}ctx.strokeStyle='#d4a34e';ctx.lineWidth=1;ctx.stroke()}}
  for(var cc=0;cc<cases.length;cc++){var pa=cases[cc],color=cases.length>1?['#3778c2','#e37b35','#c34e72'][cc]:'#2878bd';ctx.beginPath();for(var k=0;k<pa.length;k++){var pp3=P(pa[k][0],pa[k][1],pa[k][2]);if(k===0)ctx.moveTo(pp3[0],pp3[1]);else ctx.lineTo(pp3[0],pp3[1])}ctx.strokeStyle=color;ctx.lineWidth=cc===1||cases.length===1?3:2;ctx.stroke();for(var m=0;m<pa.length;m+=Math.max(1,Math.floor(pa.length/9))){var pt=P(pa[m][0],pa[m][1],pa[m][2]);ctx.fillStyle=color;ctx.beginPath();ctx.arc(pt[0],pt[1],3,0,Math.PI*2);ctx.fill()}}
  var cur=main[main.length-1],cp=P(cur[0],cur[1],cur[2]);ctx.fillStyle='#e34d4d';ctx.beginPath();ctx.arc(cp[0],cp[1],6,0,Math.PI*2);ctx.fill();txt('当前点',cp[0]+8,cp[1]-8,16,'#b23b3b');
  if(ar){var scale=35/R;var up=P(cur[0]+gx(cur[0])/Math.max(.01,scale),cur[1]+gy(cur[1])/Math.max(.01,scale),cur[2]);var down=P(cur[0]-gx(cur[0])/Math.max(.01,scale),cur[1]-gy(cur[1])/Math.max(.01,scale),cur[2]);arrow(cp[0],cp[1],up[0],up[1],'#d94a4a');arrow(cp[0],cp[1],down[0],down[1],'#238b68');txt('∇f',up[0]+5,up[1],16,'#b23b3b');txt('−∇f',down[0]+5,down[1],16,'#167452')}
  ctx.restore();
  var gxv=gx(cur[0]),gyv=gy(cur[1]),gn=Math.sqrt(gxv*gxv+gyv*gyv),fv=f(cur[0],cur[1]);
  txt('η='+eta.toFixed(2)+'   当前点 ('+cur[0].toFixed(2)+', '+cur[1].toFixed(2)+')   f='+fv.toFixed(3),55,450,17,'#26364a');
  txt('∇f=('+gxv.toFixed(3)+', '+gyv.toFixed(3)+')   ||∇f||='+gn.toFixed(3)+'   稳定边界 η≈5.56',55,477,16,'#526579');
  var title,caption;
  if(scene===0){title='目标函数变成三维曲面';caption='把待最小化的函数看成一座山谷，最低处就是最优解。'}
  else if(scene===1){title='梯度与最陡上升方向';caption='梯度指向函数上升最快的方向，下降应沿负梯度；它与等高线正交。'}
  else if(scene===2){title='真实迭代轨迹';caption='每一步都把当前位置代入真实梯度，轨迹随曲率改变，而不是预设直线。'}
  else{title='收敛与学习率对比';caption='η=0.3、1.5、5.5分别体现慢速、稳定和接近边界的交替振荡。'}
  if(mode==='explore'){title=fn?'各向同性二次碗面中的梯度下降':'各向异性二次碗面中的梯度下降';caption=eta>=5.56?'当前学习率达到或超过稳定边界，轨迹可能振荡或发散。':'当前轨迹由真实更新 θₖ₊₁=θₖ−η∇f(θₖ) 生成。'}
  var out={eta:eta,x0:x0,y0:y0,arrows:ar?1:0,contours:co?1:0,func:fn?1:0};
  return {metrics:{x:cur[0],y:cur[1],f:fv,gradient_norm:gn,step_count:steps,stable_boundary:2/(2*b),formula:fn?'f=0.18x²+0.18y²':'f=0.08x²+0.18y²'},controls:out,disabled:{},title:title,caption:caption};
}
